                raise ValueError(f"Discount cannot be negative: {discount_str}")
            fixed_amounts.append(fixed_amount)

    for bp in percentages:
        discount_amount = round_div(current_amount * bp, 10000, mode="half_up")
        current_amount -= discount_amount

    for fa in fixed_amounts:
        current_amount -= fa

    return max(0, current_amount)"
  }
